package com.learnagent.quiz;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.learnagent.course.CourseService;import com.learnagent.rag.LocalKnowledgeService;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.support.DefaultListableBeanFactory;import org.springframework.web.server.ResponseStatusException;
class QuizServiceTest{private QuizService service(){var f=new DefaultListableBeanFactory();return new QuizService(mock(QuizRepository.class),mock(QuestionRepository.class),mock(AnswerRecordRepository.class),mock(CourseService.class),mock(LocalKnowledgeService.class),f.getBeanProvider(org.springframework.ai.chat.client.ChatClient.Builder.class),new ObjectMapper());}@Test void rejects_generated_question_with_missing_correct_option(){var generated=new QuizDtos.GeneratedQuiz("Quiz",List.of(new QuizDtos.GeneratedQuestion("Question",List.of("A","B","C","D"),"X","Why","Permissions")));assertThatThrownBy(()->service().validate(generated)).isInstanceOf(ResponseStatusException.class);}@Test void normalizes_letter_answer_and_missing_knowledge_point(){var generated=new QuizDtos.GeneratedQuiz("Quiz",List.of(new QuizDtos.GeneratedQuestion("Question",List.of("first","second","third","fourth"),"B","Because",null)));var normalized=service().normalize(generated,null);assertThat(normalized.questions().getFirst().correctAnswer()).isEqualTo("second");assertThat(normalized.questions().getFirst().knowledgePoint()).isEqualTo("综合练习");service().validate(normalized);}@Test void grades_answers_and_rejects_repeat_submission(){QuizRepository quizzes=mock(QuizRepository.class);QuestionRepository questions=mock(QuestionRepository.class);AnswerRecordRepository answers=mock(AnswerRecordRepository.class);var f=new DefaultListableBeanFactory();QuizService service=new QuizService(quizzes,questions,answers,mock(CourseService.class),mock(LocalKnowledgeService.class),f.getBeanProvider(org.springframework.ai.chat.client.ChatClient.Builder.class),new ObjectMapper());Quiz quiz=new Quiz(UUID.randomUUID(),"Permissions",null);Question a=new Question(quiz.getId(),"q1","[\"A\",\"B\",\"C\",\"D\"]","A","because","permissions");Question b=new Question(quiz.getId(),"q2","[\"A\",\"B\",\"C\",\"D\"]","B","because","permissions");when(quizzes.findById(quiz.getId())).thenReturn(Optional.of(quiz));when(questions.findByQuizId(quiz.getId())).thenReturn(List.of(a,b));when(answers.existsByQuizId(quiz.getId())).thenReturn(false);QuizDtos.Submission result=service.submit(quiz.getId(),new QuizDtos.SubmitRequest(List.of(new QuizDtos.Answer(a.getId(),"A"),new QuizDtos.Answer(b.getId(),"D"))));assertThat(result.correctCount()).isEqualTo(1);assertThat(result.accuracy()).isEqualTo(.5);when(answers.existsByQuizId(quiz.getId())).thenReturn(true);assertThatThrownBy(()->service.submit(quiz.getId(),new QuizDtos.SubmitRequest(List.of()))).isInstanceOf(ResponseStatusException.class);}}
